1	package stowage
2	
3	import (
4		"sort"
5		"strings"
6		"sync"
7	)
8	
9	// compartment 是舱位的内部记录。
10	type compartment struct {
11		id        string
12		maxWeight int64
13		cargo     map[string]*cargo
14	}
15	
16	// cargo 是货物的内部记录。
17	type cargo struct {
18		id            string
19		weight        int64
20		destination   string
21		allowMixed    bool
22		compartmentID string // 空字符串表示未装载
23	}
24	
25	// Registry 是舱单与配载的本地登记处。
26	//
27	// Registry 的所有方法都可以安全地并发调用。
28	type Registry struct {
29		mu           sync.Mutex
30		compartments map[string]*compartment
31		cargos       map[string]*cargo
32		adjustments  map[string]*AdjustmentResult // 已成功调整的编号 -> 保存的结果快照
33		contents     map[string]string            // 已成功调整的编号 -> 规范化内容键
34	}
35	
36	// NewRegistry 创建一个空的登记处。
37	func NewRegistry() *Registry {
38		return &Registry{
39			compartments: make(map[string]*compartment),
40			cargos:       make(map[string]*cargo),
41			adjustments:  make(map[string]*AdjustmentResult),
42			contents:     make(map[string]string),
43		}
44	}
45	
46	// RegisterCompartment 登记一个舱位。
47	// 编号去掉首尾空白后不得为空，maxWeight 必须为正整数（千克）。
48	// 编号按去空白后的值识别并区分大小写；重复登记保留原记录。
49	func (r *Registry) RegisterCompartment(id string, maxWeight int64) error {
50		r.mu.Lock()
51		defer r.mu.Unlock()
52	
53		cid := strings.TrimSpace(id)
54		if cid == "" {
55			return fail(ErrInvalidID, "", "舱位编号为空")
56		}
57		if maxWeight <= 0 {
58			return fail(ErrInvalidWeight, cid, "舱位 %s 最大承重必须为正整数千克，当前为 %d", cid, maxWeight)
59		}
60		if _, exists := r.compartments[cid]; exists {
61			return fail(ErrAlreadyExists, cid, "舱位 %s 已存在", cid)
62		}
63		r.compartments[cid] = &compartment{
64			id:        cid,
65			maxWeight: maxWeight,
66			cargo:     make(map[string]*cargo),
67		}
68		return nil
69	}
70	
71	// RegisterCargo 登记一件货物。
72	// 编号与目的地去掉首尾空白后不得为空，weight 必须为正整数（千克）。
73	// 货物登记后处于未装载状态。
74	// 编号按去空白后的值识别并区分大小写；重复登记保留原记录。
75	func (r *Registry) RegisterCargo(id string, weight int64, destination string, allowMixed bool) error {
76		r.mu.Lock()
77		defer r.mu.Unlock()
78	
79		cid := strings.TrimSpace(id)
80		if cid == "" {
81			return fail(ErrInvalidID, "", "货物编号为空")
82		}
83		if weight <= 0 {
84			return fail(ErrInvalidWeight, cid, "货物 %s 重量必须为正整数千克，当前为 %d", cid, weight)
85		}
86		dest := strings.TrimSpace(destination)
87		if dest == "" {
88			return fail(ErrInvalidDestination, cid, "货物 %s 目的地为空", cid)
89		}
90		if _, exists := r.cargos[cid]; exists {
91			return fail(ErrAlreadyExists, cid, "货物 %s 已存在", cid)
92		}
93		r.cargos[cid] = &cargo{
94			id:          cid,
95			weight:      weight,
96			destination: dest,
97			allowMixed:  allowMixed,
98		}
99		return nil
100	}
101	
102	// Compartment 查询舱位的承重、已用重量、剩余重量与货物清单。
103	// 编号去掉首尾空白后识别；不存在时返回错误。
104	func (r *Registry) Compartment(id string) (*CompartmentView, error) {
105		r.mu.Lock()
106		defer r.mu.Unlock()
107	
108		cid := strings.TrimSpace(id)
109		if cid == "" {
110			return nil, fail(ErrInvalidID, "", "舱位编号为空")
111		}
112		comp, ok := r.compartments[cid]
113		if !ok {
114			return nil, fail(ErrNotFound, cid, "舱位 %s 不存在", cid)
115		}
116		return compartmentView(comp), nil
117	}
118	
119	// Cargo 查询货物的当前舱位或未装载状态。
120	// 编号去掉首尾空白后识别；不存在时返回错误。
121	func (r *Registry) Cargo(id string) (*CargoView, error) {
122		r.mu.Lock()
123		defer r.mu.Unlock()
124	
125		cid := strings.TrimSpace(id)
126		if cid == "" {
127			return nil, fail(ErrInvalidID, "", "货物编号为空")
128		}
129		c, ok := r.cargos[cid]
130		if !ok {
131			return nil, fail(ErrNotFound, cid, "货物 %s 不存在", cid)
132		}
133		return cargoView(c), nil
134	}
135	
136	// cargoView 构造货物快照（调用方持锁）。
137	func cargoView(c *cargo) *CargoView {
138		return &CargoView{
139			ID:            c.id,
140			Weight:        c.weight,
141			Destination:   c.destination,
142			AllowMixed:    c.allowMixed,
143			Loaded:        c.compartmentID != "",
144			CompartmentID: c.compartmentID,
145		}
146	}
147	
148	// compartmentView 构造舱位快照（调用方持锁）。
149	func compartmentView(comp *compartment) *CompartmentView {
150		used := sumSet(comp.cargo)
151		ids := make([]string, 0, len(comp.cargo))
152		for cid := range comp.cargo {
153			ids = append(ids, cid)
154		}
155		sort.Strings(ids)
156		views := make([]CargoView, 0, len(ids))
157		for _, cid := range ids {
158			views = append(views, *cargoView(comp.cargo[cid]))
159		}
160		return &CompartmentView{
161			ID:              comp.id,
162			MaxWeight:       comp.maxWeight,
163			UsedWeight:      used,
164			RemainingWeight: comp.maxWeight - used,
165			Cargo:           views,
166		}
167	}
168	
169	// sumSet 合计一组货物的重量（调用方持锁）。
170	func sumSet(set map[string]*cargo) int64 {
171		var sum int64
172		for _, c := range set {
173			sum += c.weight
174		}
175		return sum
176	}
177	
178	// cloneResult 复制一份调整结果，避免调用方修改影响已保存的快照。
179	func cloneResult(r *AdjustmentResult) *AdjustmentResult {
180		return &AdjustmentResult{
181			ID:                 r.ID,
182			CargoChanges:       append([]CargoChange(nil), r.CargoChanges...),
183			CompartmentChanges: append([]CompartmentChange(nil), r.CompartmentChanges...),
184		}
185	}
