1	package stowage
2	
3	import (
4		"encoding/json"
5		"math"
6		"sort"
7		"strings"
8	)
9	
10	// Adjust 提交一次调整，可同时包含多件货物的装载、卸下和移动。
11	//
12	// 调整编号遵循编号规则（去掉首尾空白后非空）。成功后以相同编号和
13	// 相同内容重复提交，返回首次成功的结果而不再改变配载，即使之后另有
14	// 调整也一样；同一编号用于不同内容被拒绝。失败的调整不占用编号，
15	// 可以修正后重试。
16	//
17	// 一次调整中的所有操作作为一个整体生效：任一操作不合法，整次调整
18	// 都不生效，货物归属与各舱位重量保持原样。合法性按全部操作完成后的
19	// 最终配载判断：舱位总重量不得超过承重；同一目的地的货物可以共舱，
20	// 不同目的地共舱时所有货物都必须允许混装。重量合计超过 int64 可表示
21	// 范围也会被拒绝。
22	func (r *Registry) Adjust(adjustmentID string, ops []Op) (*AdjustmentResult, error) {
23		r.mu.Lock()
24		defer r.mu.Unlock()
25	
26		aid := strings.TrimSpace(adjustmentID)
27		if aid == "" {
28			return nil, fail(ErrInvalidID, "", "调整编号为空")
29		}
30	
31		// f 构造带调整编号的错误。
32		f := func(kind ErrorKind, id string, format string, args ...any) *Error {
33			e := fail(kind, id, format, args...)
34			e.AdjustmentID = aid
35			return e
36		}
37	
38		// 幂等：编号已成功使用过。
39		if saved, ok := r.adjustments[aid]; ok {
40			if r.contents[aid] == canonicalKey(ops) {
41				return cloneResult(saved), nil
42			}
43			return nil, f(ErrAdjustmentIDConflict, aid, "调整编号 %s 已用于不同内容", aid)
44		}
45	
46		if len(ops) == 0 {
47			return nil, f(ErrEmptyAdjustment, aid, "调整 %s 不包含任何操作", aid)
48		}
49	
50		vops, final, affected, err := r.prepareOps(ops, f)
51		if err != nil {
52			return nil, err
53		}
54	
55		// 按最终配载校验承重与混装限制，返回第一个问题即拒绝整次调整。
56		if rej := r.firstRejection(final); rej != nil {
57			switch rej.Kind {
58			case ErrOverflow:
59				return nil, f(ErrOverflow, rej.CompartmentID, "舱位 %s 重量合计超过 int64 可表示范围", rej.CompartmentID)
60			case ErrOverweight:
61				return nil, f(ErrOverweight, rej.CompartmentID,
62					"舱位 %s 总重量 %d 千克超过最大承重 %d 千克",
63					rej.CompartmentID, rej.UsedWeight, r.compartments[rej.CompartmentID].maxWeight)
64			default:
65				return nil, f(ErrMixedLoading, rej.firstOffender(),
66					"舱位 %s 存在不同目的地货物，但货物 %s 不允许混装",
67					rej.CompartmentID, rej.firstOffender())
68			}
69		}
70	
71		// 全部合法，正式生效。先计算受影响舱位调整前后的重量。
72		cargoChanges := make([]CargoChange, 0, len(vops))
73		compChanges := make([]CompartmentChange, 0, len(affected))
74		for id := range affected {
75			compChanges = append(compChanges, CompartmentChange{
76				CompartmentID: id,
77				WeightBefore:  sumSet(r.compartments[id].cargo),
78				WeightAfter:   sumSet(final[id]),
79			})
80		}
81		sort.Slice(compChanges, func(i, j int) bool {
82			return compChanges[i].CompartmentID < compChanges[j].CompartmentID
83		})
84	
85		for _, v := range vops {
86			c := v.cargo
87			from := c.compartmentID
88			var to string
89			switch v.op.Kind {
90			case OpLoad:
91				r.compartments[v.target.id].cargo[c.id] = c
92				c.compartmentID = v.target.id
93				to = v.target.id
94			case OpUnload:
95				delete(r.compartments[from].cargo, c.id)
96				c.compartmentID = ""
97			case OpMove:
98				delete(r.compartments[from].cargo, c.id)
99				r.compartments[v.target.id].cargo[c.id] = c
100				c.compartmentID = v.target.id
101				to = v.target.id
102			}
103			cargoChanges = append(cargoChanges, CargoChange{CargoID: c.id, From: from, To: to})
104		}
105		sort.Slice(cargoChanges, func(i, j int) bool {
106			return cargoChanges[i].CargoID < cargoChanges[j].CargoID
107		})
108	
109		result := &AdjustmentResult{
110			ID:                 aid,
111			CargoChanges:       cargoChanges,
112			CompartmentChanges: compChanges,
113		}
114		r.adjustments[aid] = result
115		r.contents[aid] = canonicalKey(ops)
116		return cloneResult(result), nil
117	}
118	
119	// validOp 是一条通过逐条校验的操作，附带其涉及的内部记录。
120	type validOp struct {
121		op     Op
122		cargo  *cargo
123		target *compartment // 装载/移动的目标舱位；卸下时为 nil
124	}
125	
126	// prepareOps 逐条校验操作并在模拟配载上应用全部操作。
127	// 调用方必须持有 r.mu。任一操作不合法时返回该错误，最终配载与受影响
128	// 舱位集合只在全部操作合法时返回。受影响舱位包括各操作的原舱位与
129	// 目标舱位（交换中的两个舱位都会纳入）。
130	func (r *Registry) prepareOps(
131		ops []Op,
132		failf func(kind ErrorKind, id string, format string, args ...any) *Error,
133	) (vops []validOp, final map[string]map[string]*cargo, affected map[string]bool, err error) {
134		seen := make(map[string]bool)
135		vops = make([]validOp, 0, len(ops))
136		affected = make(map[string]bool)
137	
138		for _, op := range ops {
139			cid := strings.TrimSpace(op.CargoID)
140			if cid == "" {
141				return nil, nil, nil, failf(ErrInvalidID, "", "货物编号为空")
142			}
143			c, ok := r.cargos[cid]
144			if !ok {
145				return nil, nil, nil, failf(ErrNotFound, cid, "货物 %s 不存在", cid)
146			}
147			if seen[cid] {
148				return nil, nil, nil, failf(ErrDuplicateOp, cid, "货物 %s 在同一次调整中出现多次", cid)
149			}
150			seen[cid] = true
151	
152			switch op.Kind {
153			case OpLoad:
154				if c.compartmentID != "" {
155					return nil, nil, nil, failf(ErrStateMismatch, cid, "货物 %s 已装载于舱位 %s，不能再次装载", cid, c.compartmentID)
156				}
157				tid := strings.TrimSpace(op.Target)
158				if tid == "" {
159					return nil, nil, nil, failf(ErrInvalidID, "", "目标舱位编号为空")
160				}
161				t, ok := r.compartments[tid]
162				if !ok {
163					return nil, nil, nil, failf(ErrNotFound, tid, "舱位 %s 不存在", tid)
164				}
165				vops = append(vops, validOp{op, c, t})
166				affected[t.id] = true
167			case OpUnload:
168				if c.compartmentID == "" {
169					return nil, nil, nil, failf(ErrStateMismatch, cid, "货物 %s 未装载，不能卸下", cid)
170				}
171				vops = append(vops, validOp{op, c, nil})
172				affected[c.compartmentID] = true
173			case OpMove:
174				if c.compartmentID == "" {
175					return nil, nil, nil, failf(ErrStateMismatch, cid, "货物 %s 未装载，不能移动", cid)
176				}
177				tid := strings.TrimSpace(op.Target)
178				if tid == "" {
179					return nil, nil, nil, failf(ErrInvalidID, "", "目标舱位编号为空")
180				}
181				t, ok := r.compartments[tid]
182				if !ok {
183					return nil, nil, nil, failf(ErrNotFound, tid, "舱位 %s 不存在", tid)
184				}
185				if t.id == c.compartmentID {
186					return nil, nil, nil, failf(ErrDuplicateOp, cid, "货物 %s 已在舱位 %s，不能移动到原舱位", cid, t.id)
187				}
188				vops = append(vops, validOp{op, c, t})
189				affected[c.compartmentID] = true
190				affected[t.id] = true
191			default:
192				return nil, nil, nil, failf(ErrInvalidOp, cid, "货物 %s 的操作种类 %d 无法识别", cid, int(op.Kind))
193			}
194		}
195	
196		// 在模拟配载上应用全部操作，判断以完成后的最终状态为准。
197		final = make(map[string]map[string]*cargo, len(r.compartments))
198		for id, comp := range r.compartments {
199			set := make(map[string]*cargo, len(comp.cargo))
200			for cid, c := range comp.cargo {
201				set[cid] = c
202			}
203			final[id] = set
204		}
205		for _, v := range vops {
206			switch v.op.Kind {
207			case OpLoad:
208				final[v.target.id][v.cargo.id] = v.cargo
209			case OpUnload:
210				delete(final[v.cargo.compartmentID], v.cargo.id)
211			case OpMove:
212				delete(final[v.cargo.compartmentID], v.cargo.id)
213				final[v.target.id][v.cargo.id] = v.cargo
214			}
215		}
216		return vops, final, affected, nil
217	}
218	
219	// evaluateFinal 按最终配载评估每个舱位的承重与混装限制，一个舱位可以
220	// 同时得到重量原因（超重或溢出）与混装原因。结果不保证顺序。
221	// 调用方必须持有 r.mu。
222	func (r *Registry) evaluateFinal(final map[string]map[string]*cargo) []*Rejection {
223		var rejs []*Rejection
224		for id, set := range final {
225			comp := r.compartments[id]
226	
227			// 重量原因：溢出优先，溢出时不提供任何重量数值。
228			var sum int64
229			overflow := false
230			for _, c := range set {
231				if c.weight > math.MaxInt64-sum {
232					overflow = true
233					break
234				}
235				sum += c.weight
236			}
237			var rej *Rejection
238			if overflow {
239				rej = &Rejection{
240					CompartmentID: id,
241					Kind:          ErrOverflow,
242					MaxWeight:     comp.maxWeight,
243				}
244			} else if sum > comp.maxWeight {
245				rej = &Rejection{
246					CompartmentID:   id,
247					Kind:            ErrOverweight,
248					MaxWeight:       comp.maxWeight,
249					UsedWeight:      sum,
250					RemainingWeight: comp.maxWeight - sum,
251					Overweight:      sum - comp.maxWeight,
252				}
253			}
254	
255			// 混装原因：不同目的地共舱时，列出全部不允许混装的货物。
256			destinations := make(map[string][]string)
257			destSet := make(map[string]bool)
258			var offenders []string
259			for _, c := range set {
260				destinations[c.destination] = append(destinations[c.destination], c.id)
261				destSet[c.destination] = true
262				if !c.allowMixed {
263					offenders = append(offenders, c.id)
264				}
265			}
266			if len(destSet) > 1 && len(offenders) > 0 {
267				dests := make([]MixedDestination, 0, len(destinations))
268				for dest, ids := range destinations {
269					sorted := append([]string(nil), ids...)
270					sort.Strings(sorted)
271					dests = append(dests, MixedDestination{Destination: dest, CargoIDs: sorted})
272				}
273				sort.Slice(dests, func(i, j int) bool {
274					return dests[i].Destination < dests[j].Destination
275				})
276				sort.Strings(offenders)
277				mr := &Rejection{
278					CompartmentID:  id,
279					Kind:           ErrMixedLoading,
280					MaxWeight:      comp.maxWeight,
281					Destinations:   dests,
282					OffendingCargo: offenders,
283				}
284				if rej != nil {
285					rejs = append(rejs, rej, mr)
286				} else {
287					rejs = append(rejs, mr)
288				}
289			} else if rej != nil {
290				rejs = append(rejs, rej)
291			}
292		}
293		return rejs
294	}
295	
296	// firstRejection 以与正式调整一致的顺序返回第一个拒绝原因；没有则 nil。
297	// 调用方必须持有 r.mu。
298	func (r *Registry) firstRejection(final map[string]map[string]*cargo) *Rejection {
299		rejs := r.evaluateFinal(final)
300		if len(rejs) == 0 {
301			return nil
302		}
303		sort.Slice(rejs, func(i, j int) bool {
304			if rejs[i].CompartmentID != rejs[j].CompartmentID {
305				return rejs[i].CompartmentID < rejs[j].CompartmentID
306			}
307			return rejKindOrder(rejs[i].Kind) < rejKindOrder(rejs[j].Kind)
308		})
309		return rejs[0]
310	}
311	
312	// rejKindOrder 规定同一舱位的拒绝原因次序：重量（超重/溢出）先于混装。
313	func rejKindOrder(k ErrorKind) int {
314		switch k {
315		case ErrOverflow, ErrOverweight:
316			return 0
317		default:
318			return 1
319		}
320	}
321	
322	// firstOffender 返回混装原因中编号最小的货物，用于错误说明。
323	func (x *Rejection) firstOffender() string {
324		if len(x.OffendingCargo) == 0 {
325			return ""
326		}
327		return x.OffendingCargo[0]
328	}
329	
330	// canonicalKey 生成调整内容的规范化键：操作种类、货物、目标舱位相同
331	// 即视为相同内容，排列顺序不影响判断。
332	func canonicalKey(ops []Op) string {
333		sorted := make([]Op, len(ops))
334		for i, op := range ops {
335			sorted[i] = Op{
336				Kind:    op.Kind,
337				CargoID: strings.TrimSpace(op.CargoID),
338				Target:  strings.TrimSpace(op.Target),
339			}
340		}
341		sort.Slice(sorted, func(i, j int) bool {
342			if sorted[i].Kind != sorted[j].Kind {
343				return sorted[i].Kind < sorted[j].Kind
344			}
345			if sorted[i].CargoID != sorted[j].CargoID {
346				return sorted[i].CargoID < sorted[j].CargoID
347			}
348			return sorted[i].Target < sorted[j].Target
349		})
350		b, err := json.Marshal(sorted)
351		if err != nil {
352			// Op 仅含基本类型，不会失败。
353			panic(err)
354		}
355		return string(b)
356	}
357

